<evo-video ...input playing:=playing muted:=muted volume:=volume>
  <@source src="https://ir.ebaystatic.com/cr/v/c1/ebayui/video/v1/playlist.mpd"/>
</evo-video>

<p>
  The video is ${playing ? "playing" : "paused"}, ${muted ? "muted" : `at volume ${Math.round(volume * 100)}%`}
</p>

import type { Input as VideoInput } from "../index.marko";
export interface Input extends VideoInput {}
// Native `width`/`height` pass through to the `<video>` element, reserving
// the correct aspect ratio before the video loads to avoid layout shift.
<evo-video ...input width=640 height=360>
  <@source src="https://ir.ebaystatic.com/cr/v/c1/ebayui/video/v1/playlist.mpd"/>
</evo-video>

import type { Input as VideoInput } from "../index.marko";
export interface Input extends VideoInput {}

<evo-video ...input>
  <@source src="https://ir.ebaystatic.com/cr/v/c1/ebayui/video/v1/playlist.mpd"/>
  <@report
    a11yText="Report this video"
    onClick() {
      console.log("reported");
    }
  />
</evo-video>

import type { Input as VideoInput } from "../index.marko";
export interface Input extends VideoInput {}

<evo-video ...input muted autoplay offscreenPause>
  <@source src="https://ir.ebaystatic.com/cr/v/c1/ebayui/video/v1/playlist.mpd"/>
  <@nav href="https://www.ebay.com" target="_blank"/>
</evo-video>

